mapper.select:
SELECT id FROM pending_action
WHERE user_id = #{userId} AND conversation_id = #{conversationId}
  AND tool_name = 'order_create' AND status IN ('APPROVED', 'EXECUTED', 'FAILED')
ORDER BY created_at DESC, id DESC LIMIT #{limit}

mapper.update:
UPDATE pending_action SET status = 'EXECUTED', result = #{result},
                          executed_at = CURRENT_TIMESTAMP, version = version + 1
WHERE id = #{id} AND status = 'APPROVED' AND version = #{version}

UPDATE pending_action SET status = 'FAILED', result = #{result},
                          executed_at = CURRENT_TIMESTAMP, version = version + 1
WHERE id = #{id} AND status = 'APPROVED' AND version = #{version}
